"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * SORTABLE LIST: reorder by hand, and watch everything move
 *
 *   lift      press the grip and the row lifts: a darker thin line,
 *             a touch larger, above the rest; no shadow
 *   drag      it follows your finger exactly; the rows it passes
 *             slide out of its way, one slot at a time
 *   drop      it settles into its slot with a small overshoot,
 *             every rank number rolls to its new place, and the
 *             row you moved says how far it went ("↑ 2") for a
 *             moment
 *   sort      optional presets ("Votes", "Effort") re-sort the
 *             whole list and every row glides to where it belongs;
 *             the highlight slides to the preset, and fades when
 *             you've made your own order
 *   keys      Space on a grip picks the row up, arrows move it,
 *             Space drops it, Escape puts it back; every step is
 *             announced
 * ───────────────────────────────────────────────────────── */

export interface SortableListSort<T> {
  label: string;
  compare: (a: T, b: T) => number;
}

export interface SortableListProps<T extends { id: string }> extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "children"
> {
  items: T[];
  onReorder: (items: T[]) => void;
  renderItem: (
    item: T,
    state: { index: number; lifted: boolean },
  ) => React.ReactNode;
  /** What to call an item when announcing moves; defaults to its id. */
  getLabel?: (item: T) => string;
  /** Ready-made orders shown as a segmented control above the list. */
  sorts?: SortableListSort<T>[];
  /** Accessible name for the list. */
  label?: string;
}

import {
  EASE_OUT,
  EASE_SETTLE,
  rubberBand,
  projectInertia,
  samplePointer,
  releaseVelocity,
  type PointerSample,
} from "./imported-ui-interaction-motion";

const EASE = EASE_OUT;
const THROW = EASE_SETTLE;
const GAP = 6;
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const move = <T,>(list: T[], from: number, to: number) => {
  const next = list.slice();
  const [item] = next.splice(from, 1);
  next.splice(to, 0, item);
  return next;
};

function Grip() {
  return (
    <svg
      width="10"
      height="14"
      viewBox="0 0 10 14"
      aria-hidden="true"
      className="fill-current"
    >
      {[2, 7, 12].map((y) => (
        <React.Fragment key={y}>
          <circle cx="2.5" cy={y} r="1.25" />
          <circle cx="7.5" cy={y} r="1.25" />
        </React.Fragment>
      ))}
    </svg>
  );
}

export function SortableList<T extends { id: string }>({
  items,
  onReorder,
  renderItem,
  getLabel = (item) => item.id,
  sorts,
  label = "Reorderable list",
  className = "",
  ...props
}: SortableListProps<T>) {
  const reduced = useReducedMotion();
  const uid = React.useId();
  const listRef = React.useRef<HTMLUListElement>(null);
  const rows = React.useRef(new Map<string, HTMLLIElement>());
  const handles = React.useRef(new Map<string, HTMLButtonElement>());
  const offsets = React.useRef(new Map<string, number>());
  const pending = React.useRef<{
    first: Map<string, number>;
    settle?: string;
    focus?: string;
  } | null>(null);
  const drag = React.useRef<{
    id: string;
    from: number;
    to: number;
    startY: number;
    tops: number[];
    heights: number[];
  } | null>(null);
  const samples = React.useRef<PointerSample[]>([]);
  const [lifted, setLifted] = React.useState<string | null>(null);
  const [keyLift, setKeyLift] = React.useState<{
    id: string;
    from: number;
  } | null>(null);
  const [moved, setMoved] = React.useState<{
    id: string;
    by: number;
    key: number;
  } | null>(null);
  const [announce, setAnnounce] = React.useState("");

  // Where every row is on screen right now (its slot plus any shift), for gliding from there.
  const snapshot = () => {
    const first = new Map<string, number>();
    rows.current.forEach((el, id) =>
      first.set(id, el.offsetTop + (offsets.current.get(id) ?? 0)),
    );
    return first;
  };

  const shift = (id: string, y: number, glide: boolean) => {
    const el = rows.current.get(id);
    if (!el) return;
    offsets.current.set(id, y);
    el.style.transition =
      glide && !reduced ? `transform 220ms ${EASE}` : "none";
    el.style.transform = y ? `translateY(${y}px)` : "";
  };

  // After any new order: every row glides from where it was to its new slot.
  const play = React.useCallback(() => {
    const p = pending.current;
    if (!p) return;
    pending.current = null;
    rows.current.forEach((el, id) => {
      el.style.transition = "none";
      el.style.transform = "";
      offsets.current.set(id, 0);
      const from = p.first.get(id);
      if (from === undefined || reduced) return;
      const delta = from - el.offsetTop;
      if (Math.abs(delta) < 0.5) return;
      el.animate(
        [{ transform: `translateY(${delta}px)` }, { transform: "none" }],
        {
          duration: id === p.settle ? 360 : 380,
          easing: id === p.settle ? THROW : EASE,
        },
      );
    });
    if (p.focus) handles.current.get(p.focus)?.focus({ preventScroll: true });
  }, [reduced]);

  React.useLayoutEffect(() => {
    play();
  }, [items, play]);

  const commit = (next: T[], settle?: string, focus?: string) => {
    pending.current = { first: snapshot(), settle, focus };
    onReorder(next);
    // If the order didn't change after all, still put everything back.
    requestAnimationFrame(() => requestAnimationFrame(play));
  };

  const moveSeq = React.useRef(0);
  const showMoved = (id: string, by: number) => {
    if (!by) return;
    const key = ++moveSeq.current;
    setMoved({ id, by, key });
    window.setTimeout(() => setMoved((m) => (m?.key === key ? null : m)), 1800);
  };

  // Pointer dragging: transforms only until the drop.
  const onPointerDown = (
    e: React.PointerEvent<HTMLButtonElement>,
    id: string,
  ) => {
    if (e.button !== 0 || keyLift) return;
    e.preventDefault();
    e.currentTarget.setPointerCapture(e.pointerId);
    const from = items.findIndex((it) => it.id === id);
    const els = items.map((it) => rows.current.get(it.id)!);
    drag.current = {
      id,
      from,
      to: from,
      startY: e.clientY,
      tops: els.map((el) => el.offsetTop),
      heights: els.map((el) => el.offsetHeight),
    };
    samples.current = [];
    samplePointer(samples.current, e.clientY, e.timeStamp);
    setLifted(id);
  };
  const onPointerMove = (e: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    samplePointer(samples.current, e.clientY, e.timeStamp);
    const rawDy = e.clientY - d.startY;
    const minCenter = d.tops[0] + d.heights[0] / 2;
    const maxCenter =
      d.tops[d.tops.length - 1] + d.heights[d.heights.length - 1] / 2;
    const naturalCenter = d.tops[d.from] + d.heights[d.from] / 2 + rawDy;

    // Boundary elasticity: rational rubber-band past list ends
    let center = naturalCenter;
    if (naturalCenter < minCenter) {
      center = minCenter + rubberBand(naturalCenter - minCenter, 140, 0.45);
    } else if (naturalCenter > maxCenter) {
      center = maxCenter + rubberBand(naturalCenter - maxCenter, 140, 0.45);
    }
    const dy = center - (d.tops[d.from] + d.heights[d.from] / 2);

    let to = 0;
    items.forEach((_, i) => {
      if (i !== d.from && naturalCenter > d.tops[i] + d.heights[i] / 2) to++;
    });
    d.to = to;
    shift(d.id, dy, false);
    const step = d.heights[d.from] + GAP;
    items.forEach((it, i) => {
      if (i === d.from) return;
      const y =
        d.from < to && i > d.from && i <= to
          ? -step
          : d.from > to && i < d.from && i >= to
            ? step
            : 0;
      if ((offsets.current.get(it.id) ?? 0) !== y) shift(it.id, y, true);
    });
  };
  const onPointerUp = (e?: React.PointerEvent) => {
    const d = drag.current;
    if (!d) return;
    let to = d.to;
    if (e) {
      samplePointer(samples.current, e.clientY, e.timeStamp);
      const vy = releaseVelocity(samples.current, e.timeStamp);
      if (Math.abs(vy) > 0.35) {
        const rawDy = e.clientY - d.startY;
        const naturalCenter = d.tops[d.from] + d.heights[d.from] / 2 + rawDy;
        const projected = projectInertia(naturalCenter, vy, 0.1);
        let projectedTo = 0;
        items.forEach((_, i) => {
          if (i !== d.from && projected > d.tops[i] + d.heights[i] / 2)
            projectedTo++;
        });
        to = projectedTo;
      }
    }
    drag.current = null;
    setLifted(null);
    const item = items[d.from];
    commit(move(items, d.from, to), d.id);
    showMoved(d.id, d.from - to);
    if (to !== d.from)
      setAnnounce(
        `${getLabel(item)} moved to position ${to + 1} of ${items.length}.`,
      );
  };

  // Keyboard: Space picks up and drops, arrows move one place, Escape puts it back.
  const onKeyDown = (e: React.KeyboardEvent, id: string) => {
    const index = items.findIndex((it) => it.id === id);
    const item = items[index];
    if (e.key === " " || e.key === "Enter") {
      e.preventDefault();
      if (keyLift?.id === id) {
        setKeyLift(null);
        setLifted(null);
        showMoved(id, keyLift.from - index);
        setAnnounce(
          `${getLabel(item)} dropped at position ${index + 1} of ${items.length}.`,
        );
      } else {
        setKeyLift({ id, from: index });
        setLifted(id);
        setAnnounce(
          `${getLabel(item)} picked up, position ${index + 1} of ${items.length}. Arrow keys move it, Space drops it, Escape cancels.`,
        );
      }
      return;
    }
    if (keyLift?.id !== id) return;
    if (e.key === "ArrowUp" || e.key === "ArrowDown") {
      e.preventDefault();
      const to = Math.max(
        0,
        Math.min(items.length - 1, index + (e.key === "ArrowUp" ? -1 : 1)),
      );
      if (to === index) return;
      commit(move(items, index, to), id, id);
      setAnnounce(`${getLabel(item)}, position ${to + 1} of ${items.length}.`);
    }
    if (e.key === "Escape") {
      e.preventDefault();
      commit(move(items, index, keyLift.from), id, id);
      setKeyLift(null);
      setLifted(null);
      setAnnounce(
        `${getLabel(item)} put back at position ${keyLift.from + 1}.`,
      );
    }
  };

  // Presets: which one the current order matches, and a highlight that slides to it.
  const sortRefs = React.useRef<(HTMLButtonElement | null)[]>([]);
  const active = sorts
    ? sorts.findIndex((s) =>
        items.every((it, i) => i === 0 || s.compare(items[i - 1], it) <= 0),
      )
    : -1;
  const [mark, setMark] = React.useState({
    x: 0,
    w: 0,
    on: false,
    slide: false,
  });
  React.useLayoutEffect(() => {
    const el = sortRefs.current[active];
    setMark((m) =>
      el
        ? { x: el.offsetLeft, w: el.offsetWidth, on: true, slide: m.on }
        : { ...m, on: false, slide: false },
    );
  }, [active]);

  return (
    <div className={`w-full ${className}`} {...props}>
      {sorts && sorts.length > 0 && (
        <div className="mb-3 flex items-center justify-between gap-3">
          <div
            role="group"
            aria-label="Sort by"
            className="relative flex rounded-full border border-border p-0.5"
          >
            <span
              aria-hidden="true"
              className="absolute bottom-0.5 left-0 top-0.5 rounded-full bg-accent"
              style={{
                transform: `translateX(${mark.x}px)`,
                width: mark.w,
                opacity: mark.on ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `${mark.slide ? `transform 360ms ${EASE}, width 360ms ${EASE}, ` : ""}opacity 220ms ${EASE}`,
              }}
            />
            {sorts.map((s, i) => (
              <button
                key={s.label}
                ref={(el) => {
                  sortRefs.current[i] = el;
                }}
                type="button"
                aria-pressed={i === active}
                onClick={() => {
                  const next = items.slice().sort(s.compare);
                  commit(next);
                  setAnnounce(`Sorted by ${s.label}.`);
                }}
                className={`cursor-pointer relative h-7 rounded-full px-3 text-[12.5px] transition-colors duration-200 ${FOCUS} ${
                  i === active
                    ? "font-medium text-foreground"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                {s.label}
              </button>
            ))}
          </div>
          <span
            className="text-[12px] text-muted-foreground"
            style={{
              opacity: active === -1 ? 1 : 0,
              transition: reduced ? "none" : `opacity 220ms ${EASE}`,
            }}
            aria-hidden={active !== -1}
          >
            Your order
          </span>
        </div>
      )}

      <ul
        ref={listRef}
        aria-label={label}
        className="relative flex flex-col"
        style={{ gap: GAP }}
        onPointerMove={onPointerMove}
        onPointerUp={onPointerUp}
        onPointerCancel={onPointerUp}
      >
        {items.map((item, index) => {
          const up = lifted === item.id;
          const badge = moved?.id === item.id ? moved : null;
          return (
            <li
              key={item.id}
              ref={(el) => {
                if (el) rows.current.set(item.id, el);
                else rows.current.delete(item.id);
              }}
              className="relative"
              style={{ zIndex: up ? 2 : undefined }}
            >
              <div
                className="relative flex min-h-12 items-center gap-2.5 rounded-[12px] border bg-card py-2 pl-1.5 pr-3"
                style={{
                  borderColor: up
                    ? "color-mix(in oklab, var(--foreground) 28%, transparent)"
                    : "var(--border)",
                  transform: up ? "scale(1.015)" : "none",
                  transition: reduced
                    ? "none"
                    : `transform 200ms ${EASE}, border-color 200ms`,
                }}
              >
                <button
                  ref={(el) => {
                    if (el) handles.current.set(item.id, el);
                    else handles.current.delete(item.id);
                  }}
                  type="button"
                  aria-label={`Reorder ${getLabel(item)}`}
                  aria-describedby={`${uid}-how`}
                  aria-pressed={keyLift?.id === item.id}
                  onPointerDown={(e) => onPointerDown(e, item.id)}
                  onKeyDown={(e) => onKeyDown(e, item.id)}
                  onBlur={() => {
                    if (keyLift?.id === item.id && !pending.current) {
                      setKeyLift(null);
                      setLifted(null);
                    }
                  }}
                  className={`flex h-8 w-6 shrink-0 touch-none items-center justify-center rounded-[8px] text-muted-foreground/70 transition-colors hover:bg-accent hover:text-foreground ${
                    up
                      ? "cursor-grabbing bg-accent text-foreground"
                      : "cursor-grab"
                  } ${FOCUS}`}
                >
                  <Grip />
                </button>
                <span
                  className="w-5 shrink-0 text-[12px] tabular-nums text-muted-foreground"
                  aria-hidden="true"
                >
                  <NumberRoll value={index + 1} duration={500} />
                </span>
                <div className="min-w-0 flex-1">
                  {renderItem(item, { index, lifted: up })}
                </div>
                {/* How far it moved, sitting on the row's top edge so nothing shifts. */}
                {badge && (
                  <span
                    key={badge.key}
                    aria-hidden="true"
                    className="pointer-events-none absolute -top-2.5 right-3 rounded-full border border-border bg-card px-1.5 text-[11px] font-medium leading-[18px] tabular-nums text-foreground"
                    ref={(el) => {
                      if (!el || reduced || el.dataset.in) return;
                      el.dataset.in = "1";
                      el.animate(
                        [
                          {
                            opacity: 0,
                            filter: "blur(4px)",
                            transform: "translateY(4px)",
                          },
                          {
                            opacity: 1,
                            filter: "blur(0px)",
                            transform: "none",
                            offset: 0.15,
                          },
                          {
                            opacity: 1,
                            filter: "blur(0px)",
                            transform: "none",
                            offset: 0.8,
                          },
                          {
                            opacity: 0,
                            filter: "blur(4px)",
                            transform: "translateY(-4px)",
                          },
                        ],
                        { duration: 1800, easing: EASE, fill: "forwards" },
                      );
                    }}
                  >
                    {badge.by > 0 ? "↑" : "↓"} {Math.abs(badge.by)}
                  </span>
                )}
              </div>
            </li>
          );
        })}
      </ul>
      <p id={`${uid}-how`} className="sr-only">
        Press Space to pick up, arrow keys to move, Space to drop, Escape to
        cancel.
      </p>
      <p className="sr-only" role="status">
        {announce}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";

export const EASE_OUT = "cubic-bezier(0.16, 1, 0.3, 1)";
export const EASE_SETTLE = "cubic-bezier(0.22, 1.18, 0.36, 1)";
/** Thrown things (indicators, thumbs): a slight overshoot on transform only. */
export const EASE_THROW = "cubic-bezier(0.34, 1.36, 0.64, 1)";
/**
 * The press every button primitive shares: a 3% give that eases in and settles back.
 * Tailwind v4's scale-* writes the `scale` property, so `scale` has to be in the list
 * or the press snaps.
 */
export const INTERACTION_PRESS =
  "transition-[background-color,color,box-shadow,opacity,scale] duration-200 ease-[cubic-bezier(0.16,1,0.3,1)] active:scale-[0.97] motion-reduce:transition-none motion-reduce:active:scale-100";
export const INTERACTION_FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const query = "(prefers-reduced-motion: reduce)";
const subscribe = (notify: () => void) => {
  const media = window.matchMedia(query);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
export const useInteractionReducedMotion = () =>
  React.useSyncExternalStore(
    subscribe,
    () => window.matchMedia(query).matches,
    () => false,
  );

export function useInteractionActivity<T extends Element>() {
  const ref = React.useRef<T>(null);
  const [visible, setVisible] = React.useState(false);
  const [hidden, setHidden] = React.useState(false);
  React.useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const observer = new IntersectionObserver(([entry]) =>
      setVisible(entry.isIntersecting),
    );
    observer.observe(el);
    const visibility = () => setHidden(document.hidden);
    visibility();
    document.addEventListener("visibilitychange", visibility);
    return () => {
      observer.disconnect();
      document.removeEventListener("visibilitychange", visibility);
    };
  }, []);
  return { ref, active: visible && !hidden };
}

export function interactionIcon(
  on: boolean,
  reduced: boolean,
): React.CSSProperties {
  return {
    opacity: on ? 1 : 0,
    transform: on ? "none" : "scale(0.6)",
    filter: on ? "blur(0px)" : "blur(3px)",
    transition: reduced
      ? "none"
      : `opacity 220ms ${EASE_OUT}, transform 380ms ${EASE_OUT}, filter 220ms ${EASE_OUT}`,
  };
}

/** Sample recent movement rather than averaging a long drag and losing its release velocity. */
export type PointerSample = { x: number; time: number };
export function samplePointer(
  samples: PointerSample[],
  x: number,
  time: number,
) {
  samples.push({ x, time });
  while (samples.length > 2 && time - samples[0].time > 100) samples.shift();
}
export function releaseVelocity(samples: PointerSample[], now: number) {
  if (samples.length < 2 || now - samples[samples.length - 1].time > 100)
    return 0;
  const first = samples[0],
    last = samples[samples.length - 1];
  return (last.x - first.x) / Math.max(1, last.time - first.time);
}

/** Smooth Apple/rational rubber-band curve: continuous exponential-like resistance without linear kinks. */
export function rubberBand(
  overshoot: number,
  dimension = 320,
  constant = 0.55,
): number {
  const d = dimension || 320;
  const abs = Math.abs(overshoot);
  return Math.sign(overshoot) * (1 - 1 / ((abs * constant) / d + 1)) * d;
}

/** Projects resting travel from release velocity (velocity in px/ms; time in seconds). */
export function projectInertia(
  distance: number,
  velocity: number,
  time = 0.12,
): number {
  return distance + velocity * 1000 * time;
}

/** Smooths incoming release velocity toward a boundary so springs don't slam or clip into walls. */
export function softenVelocity(
  velocity: number,
  distanceToTarget: number,
  factor = 10,
): number {
  const maxAllowed = Math.abs(distanceToTarget) * factor;
  return Math.sign(velocity) * Math.min(Math.abs(velocity), maxAllowed);
}

/** A damped spring sampled by WAAPI: tuned for organic lightness with a hint of life (3% breath). */
export function springFrames(
  from: number,
  to: number,
  velocity = 0,
  duration = 480,
  config: { omega?: number; damping?: number; steps?: number } = {},
) {
  const { omega = 16, damping = 0.74, steps = 36 } = config;
  const damped = omega * Math.sqrt(Math.max(0.001, 1 - damping * damping));
  const displacement = from - to;
  const coefficient =
    (velocity * 1000 + damping * omega * displacement) / damped;
  return Array.from({ length: steps + 1 }, (_, i) => {
    const t = (i / steps) * (duration / 1000);
    const value =
      to +
      Math.exp(-damping * omega * t) *
        (displacement * Math.cos(damped * t) +
          coefficient * Math.sin(damped * t));
    return { value: i === steps ? to : value, offset: i / steps };
  });
}

